#!/usr/bin/env node
/**
 * Vendor the eks-agent-platform CRD schemas this repo validates `platform.yaml`
 * against, and record their provenance.
 *
 * The CRDs are generated by controller-gen in nanohype/eks-agent-platform under
 * `operators/config/crd/bases/`. `platform.yaml` is applied against those exact
 * schemas, so the validation gate needs them — but a CI runner has no sibling
 * checkout, and resolving them over the network at gate time makes the gate's
 * verdict depend on whatever upstream happens to be that minute.
 *
 * So the copies live in this repo under `schemas/crd/`, alongside
 * `schemas/crd/provenance.json` recording the upstream repository, the commit
 * they were taken from, and a SHA-256 for each file. The gate reads the copies
 * off disk and verifies those digests, so it is deterministic, needs no
 * network, and cannot silently degrade into a no-op when a schema is missing.
 *
 *   node scripts/sync-crd-schemas.mjs          # re-vendor from a local checkout
 *   node scripts/sync-crd-schemas.mjs --check  # fail if a copy drifted from it
 *
 * The upstream checkout resolves from $EKS_AGENT_PLATFORM_DIR, defaulting to a
 * sibling at ../eks-agent-platform. `--check` is a maintainer command: it needs
 * that checkout and fails loudly without one. CI does NOT run it — CI validates
 * against the vendored copies and their digests, which is the whole point.
 *
 * Re-vendor when eks-agent-platform's API types change: run this script, review
 * the schema diff, and ship it with whatever `platform.yaml` change it implies.
 */
import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const ROOT = join(SCRIPT_DIR, "..");
const PROVENANCE_PATH = join(ROOT, "schemas", "crd", "provenance.json");
const UPSTREAM_DIR = process.env.EKS_AGENT_PLATFORM_DIR ?? join(ROOT, "..", "eks-agent-platform");
const CHECK = process.argv.includes("--check");

const out = (line) => process.stdout.write(`${line}\n`);
const digest = (buf) => createHash("sha256").update(buf).digest("hex");

async function run() {
  const provenance = JSON.parse(await readFile(PROVENANCE_PATH, "utf8"));
  const upstreamRoot = join(UPSTREAM_DIR, provenance.sourcePath);

  let commit = provenance.commit;
  if (!CHECK) {
    const { execFile } = await import("node:child_process");
    const { promisify } = await import("node:util");
    const { stdout } = await promisify(execFile)("git", ["-C", UPSTREAM_DIR, "rev-parse", "HEAD"]);
    commit = stdout.trim();
  }

  const drift = [];
  const files = [];

  for (const entry of provenance.files) {
    const upstream = await readFile(join(upstreamRoot, entry.file));
    const localPath = join(ROOT, "schemas", "crd", entry.file);

    if (CHECK) {
      const local = await readFile(localPath);
      if (!local.equals(upstream)) drift.push(entry.file);
      if (digest(local) !== entry.sha256) drift.push(`${entry.file} (provenance digest)`);
    } else {
      await writeFile(localPath, upstream);
      out(`vendored schemas/crd/${entry.file}`);
    }
    files.push({ file: entry.file, sha256: digest(upstream) });
  }

  if (CHECK) {
    if (drift.length > 0) {
      process.stderr.write(
        `CRD schema drift against ${upstreamRoot}:\n${drift.map((d) => `  - ${d}`).join("\n")}\n` +
          "Run `npm run sync:crd-schemas` and review the schema diff.\n",
      );
      process.exit(1);
    }
    out(`CRD schemas match ${upstreamRoot} (${provenance.files.length} files)`);
    return;
  }

  await writeFile(
    PROVENANCE_PATH,
    `${JSON.stringify({ ...provenance, commit, files }, null, 2)}\n`,
  );
  out(`provenance pinned to ${provenance.repository}@${commit}`);
}

run().catch((err) => {
  process.stderr.write(`sync-crd-schemas failed: ${err.message}\n`);
  process.exit(1);
});
